class ControllerVoiceLongPrefix final {
 using T=MidiVoiceModulationTask;using S=T::Stage;using V=VoiceAddressTask;
public:
 explicit ControllerVoiceLongPrefix(uint32_t patch):patch_(patch){}bool complete()const{return final_&&final_->complete();}bool awaitingDsp()const{return final_?final_->awaitingDsp():portamento_?portamento_->awaitingDsp():glide_?glide_->awaitingDsp():dsp_&&dsp_->awaitingDsp();}uint16_t address()const{return final_?final_->address():portamento_?portamento_->address():glide_?glide_->address():dsp_?dsp_->address():0;}uint32_t word()const{return final_?final_->word():portamento_?portamento_->word():glide_?glide_->word():dsp_?dsp_->word():0;}bool resumeDsp(){if(!awaitingDsp())return false;auto ok=final_?final_->resumeDsp():portamento_?portamento_->resumeDsp():glide_?glide_->resumeDsp():dsp_->resumeDsp();if(ok&&portamento_&&!final_&&portamento_->complete())final_.emplace(patch_);return ok;}
 bool stackWrites()const{if(final_)return final_->stackWrites();if(portamento_)return portamento_->stackWrites();if(timing_)return timing_->stackWrites();if(glide_)return glide_->stackWrites();if(dsp_)return dsp_->stackWrites();if(voice_)return false;return task_.stage()==S::VoiceAddress||task_.stage()==S::SendCommand;}
 unsigned nextClocks(int previous=-1)const{if(final_)return final_->nextClocks();if(portamento_)return portamento_->nextClocks();if(timing_)return timing_->nextClocks();if(glide_)return glide_->nextClocks(previous);if(dsp_)return dsp_->nextClocks();if(voice_){V::Credits c{3,7};return voice_->nextClocks(c);}switch(task_.stage()){case S::AwaitChild:case S::Complete:return 0;case S::VoiceAddress:case S::SendCommand:return 10;case S::ReadSource:return 12+bus(voiceAddress_+6);case S::ReadDepth:{constexpr uint32_t off[]={0x3a,0x3d,0x42};return 12+bus(patch_+off[task_.index()]);}case S::Multiply:return 18;case S::BindCommand:return 6;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,R&&read,W&&write,int previous=-1){auto cost=nextClocks(previous);if(!cost||cost>budget)return 0;if(final_)return final_->advanceBefore(cost,read);if(portamento_){auto used=portamento_->advanceBefore(cost,read);if(portamento_->complete())final_.emplace(patch_);return used;}if(timing_){auto used=timing_->advanceBefore(cost,read);if(timing_->complete())portamento_.emplace(patch_,timing_->result());return used;}if(glide_){auto used=glide_->advanceBefore(cost,read,write,previous);if(glide_->complete())timing_.emplace(patch_);return used;}if(dsp_){auto used=dsp_->advanceBefore(cost,read);if(dsp_->complete()){dsp_.reset();task_.resume(T::Child::SendCommand);if(task_.awaitingChild()&&task_.child()==T::Child::ContinueLong)glide_.emplace(patch_);}return used;}if(voice_){V::Credits c{3,7};auto used=voice_->advanceBefore(cost,c,[&](){return read(0xd023,1,cost);});if(voice_->complete()){voiceAddress_=voice_->address();voice_.reset();task_.resume(T::Child::VoiceAddress);}return used;}bool used=task_.advance([&](T::Read f){constexpr uint32_t off[]={0x3a,0x3d,0x42};auto a=f==T::Read::Source?voiceAddress_+6:patch_+off[task_.index()];return uint8_t(read(a&0xffffff,1,cost));});if(!used)return 0;if(task_.awaitingChild()){if(task_.child()==T::Child::VoiceAddress)voice_.emplace();else if(task_.child()==T::Child::SendCommand){constexpr uint16_t cmd[]={0x4f,0x52,0x58};dsp_.emplace(cmd[task_.index()],uint32_t(task_.coefficient())<<8);}}return cost;}
private:static unsigned bus(uint32_t a){return (a&0xffffff)<0xfffd10?3:1;}uint32_t patch_,voiceAddress_=0;T task_{};std::optional<V>voice_{};std::optional<ControllerVoiceDspWordTask>dsp_{};std::optional<ControllerVoiceLongGlide>glide_{};std::optional<ControllerVoiceLongTiming>timing_{};std::optional<ControllerVoiceLongPortamento>portamento_{};std::optional<ControllerVoiceLongFinal>final_{};
};
